        const [o1, o2, o3] = [1, 2, 3].map(obstacle), ours = [o1, o2, o3].map(o => o.nonce);
        const without = nonce => ({ [flag]: listOf(theirs.getFlag(MODULE_ID, FLAGS.pendingCall)).filter(c => c.nonce !== nonce) });
        const from = Date.now(), made = [];
