            await set("dailyLife");
            const bet = async target => M.cubAbilityOnGm({ actorId: cub.id, key: "bet", targetId: target.id, choice: "bet" });
            await S.cubStore.patch(cub.id, { witness: { chapter, epoch: seasonEpoch() } });
