            api: ["function", "function"],
            guard: [null, null, ["bridge.refused"]],
            start: ["testimony", true, true],
            done: [["bridge.refused"], ["bridge.refused"], ["bridge.done"], true],
            moved: true,
            over: [["bridge.refused"], overWant, true, overWant ? ["bridge.refused"] : ["none"]],
