            await game.settings.set(MODULE_ID, SETTINGS.trialProgress, progress);
            await setClock(clock);
            const fresh = game.messages.filter(m => !seen.has(m.id)).map(m => m.id);
            if (fresh.length) await ChatMessage.deleteDocuments(fresh);
