            read = [rest?.verdict ?? null, foundry.utils.getProperty(student._source, HOPE), student.getFlag(MODULE_ID, FLAGS.restsTaken) ?? null,
                rows.map(row => `${row.verdict}:${Object.keys(row.change ?? {}).sort().join(",")}`)];
