            const [one, two, den] = await scene.createEmbeddedDocuments("Region", [{ name: K, shapes: box(0), flags: mark, behaviors: [] },
                { name: K, shapes: box(2000), flags: mark, behaviors: [] }, { name: DEN, shapes: box(3000), flags: mark, behaviors: [] }]);
