                await other.createEmbeddedDocuments("Region", [{ name: "SUITE E12 fix r1-G2 a hall", shapes: [{ type: "rectangle", x: 0, y: 0, width: 800, height: 800 }],
                    flags: { [MODULE_ID]: { [R.ROOM_FLAG]: true } }, behaviors: [] }]);
