            const [halt] = await scene("a place the carrying GM left", [room(DEN, 0)]);
            const [haltedToken] = await halt.createEmbeddedDocuments("Token", [token(halted, 300, 300)]);
            const haltDelete = halt.deleteEmbeddedDocuments.bind(halt);
