                await S.trialCastStore.patchMany({ [old[0]]: { reveal: false, epoch }, [old[1]]: { reveal: true, epoch }, [old[2]]: { reveal: true, epoch },
                    [T.castKey(hall.id, second.id)]: { reveal: false, epoch } });
                await settle();
