            for (const a of trio) for (const i of a.items.filter(i => i.name === NAME || i.name === FULL)) await i.delete();
            for (const [i, was] of stowed) if (victim.items.has(i.id)) await i.update({ [flag("location")]: was ?? forcedDeletion() });
