            await worn.update({ [WEAR]: 2 });
            await less.update({ [WEAR]: 1 });
            await broken.update({ [BROKEN]: { at: Date.now() } });
            await sheetAuditIdle();
            const lines = await applyEffects(actor, [effect], where, player);
