            read.pick = [await reroll("pick", { pickRoom: B, opened: false, coverTotal: 20, coverCritical: false }), M.roomOfToken(scene.tokens.get(token.id)) === B
                ? "walked" : (await import("./lockpick-gm.mjs")).passOf(actor.id)?.room ?? null];
